<?php require_once __DIR__ . '/includes/config.php';role(['admin','payroll','auditor']);$p=db();if($_SERVER['REQUEST_METHOD']==='POST'){check();$s=$p->prepare('SELECT id FROM employees WHERE employee_no=?');$s->execute([$_POST['employee_no']]);$eid=$s->fetchColumn();$p->prepare('INSERT INTO payroll(employee_id,employee_no,pay_period,gross_amount,payment_reference,payment_date) VALUES(?,?,?,?,?,?)')->execute([$eid?:null,$_POST['employee_no'],$_POST['pay_period'],$_POST['gross_amount'],$_POST['payment_reference'],$_POST['payment_date']?:null]);log_action('ADD_PAYROLL',$_POST['employee_no']);$_SESSION['flash']='Payroll record saved';header('Location:payroll.php');exit;}$rows=$p->query('SELECT p.*,e.full_name,e.employment_status FROM payroll p LEFT JOIN employees e ON e.id=p.employee_id ORDER BY p.id DESC')->fetchAll();head('Payroll');?><h1>Payroll records</h1><?php if(in_array($_SESSION['user']['role'],['admin','payroll'])):?><form class="panel grid" method="post"><input type="hidden" name="token" value="<?=e(token())?>"><label>Employee number<input name="employee_no" required></label><label>Period YYYY-MM<input name="pay_period" pattern="\d{4}-\d{2}" required></label><label>Gross amount<input name="gross_amount" type="number" min="0" step=".01" required></label><label>Payment reference<input name="payment_reference"></label><label>Payment date<input name="payment_date" type="date"></label><button>Add payroll</button></form><?php endif;?><div class="panel table"><table><tr><th>Employee no.</th><th>Name</th><th>Status</th><th>Period</th><th>Amount</th><th>Reference</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['employee_no'])?></td><td><?=e($r['full_name']??'Unmatched')?></td><td><?=e($r['employment_status']??'Unknown')?></td><td><?=e($r['pay_period'])?></td><td><?=number_format($r['gross_amount'],2)?></td><td><?=e($r['payment_reference'])?></td></tr><?php endforeach;?></table></div><?php foot();?>